12	// The scenario is trusted, not validated: this is a happy-path CLI, so a
13	// malformed payload surfaces as a JSON.parse or runScenario failure rather
14	// than a schema error.
15	const parseScenario = (input: string): Scenario => JSON.parse(input) as Scenario;
16	
17	/**
18	 * A rejection, rendered for someone reading a terminal rather than a stack
19	 * trace. `Error` is the only shape this CLI throws on purpose — anything else
20	 * reaching here is unforeseen, so it is stringified rather than assumed.
21	 */
22	const describeError = (error: unknown): string =>
23	  error instanceof Error ? error.message : String(error);
24	
25	const main = async (): Promise<void> => {
26	  const scenario = parseScenario(await readStdin());
27	
28	  process.stdout.write(JSON.stringify(runScenario(scenario)));
29	};
30	
31	try {
32	  await main();
33	} catch (error) {
34	  // Nothing is written to stdout before the scenario has run to completion, so
35	  // a rejection leaves stdout empty: the caller never sees partial results.
36	  process.stderr.write(`${describeError(error)}\n`);
37	  process.exitCode = 1;
38	}
